from __future__ import annotations

NATIVE_CHAT_HTML = r"""<!doctype html>
<html lang="zh-Hant">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>E4B Core</title>
<style>
:root{color-scheme:dark;font-family:system-ui,"Microsoft JhengHei",sans-serif;background:#11151b;color:#edf2f7}
*{box-sizing:border-box}body{margin:0}main{height:100vh;max-width:980px;margin:auto;display:grid;grid-template-rows:auto auto 1fr auto;padding:18px;gap:14px}
header{display:flex;align-items:center;justify-content:space-between;gap:12px}h1{font-size:20px;margin:0}.sub{color:#9aa7b5;font-size:13px}.actions{display:flex;gap:8px}.danger{background:#9f3541}
.controls{display:grid;grid-template-columns:auto auto 1fr;gap:12px;align-items:end;padding:12px;background:#181e26;border:1px solid #293440;border-radius:14px}.control{display:grid;gap:5px;font-size:12px;color:#aeb9c5}.toggle{display:flex;align-items:center;gap:7px;height:38px;color:#edf2f7}.toggle input{width:17px;height:17px}.control select,.control input[type=text]{height:38px;border:1px solid #35404d;border-radius:9px;background:#111820;color:inherit;padding:0 10px;font:inherit}.cwd{min-width:0}.control-title{display:flex;align-items:center;justify-content:space-between;gap:8px}.mini{padding:3px 9px;border-radius:7px;font-size:12px}
#chat{overflow:auto;display:flex;flex-direction:column;gap:12px;padding:8px 2px}.msg{max-width:82%;padding:11px 14px;border-radius:16px;white-space:pre-wrap;line-height:1.55}.user{align-self:flex-end;background:#2864dc}.assistant{align-self:flex-start;background:#202833}.notice{align-self:center;color:#e9c46a;font-size:13px;background:#29271e;padding:7px 11px;border-radius:10px;white-space:pre-wrap;max-width:90%}
form{display:grid;grid-template-columns:1fr auto;gap:10px}textarea{resize:none;min-height:54px;max-height:180px;border:1px solid #35404d;border-radius:14px;background:#181e26;color:inherit;padding:14px;font:inherit}button{border:0;border-radius:12px;padding:0 18px;background:#3b82f6;color:white;font-weight:650;cursor:pointer}button:disabled{opacity:.5}.secondary{background:#252d38;padding:9px 13px}
dialog{width:min(680px,92vw);max-height:78vh;border:1px solid #35404d;border-radius:16px;background:#151b23;color:inherit;padding:0}dialog::backdrop{background:#000a}.folder-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid #303a46}.folder-path{padding:11px 16px;color:#aeb9c5;word-break:break-all}.folder-list{display:grid;gap:5px;max-height:48vh;overflow:auto;padding:0 12px 12px}.folder-item{background:#222b36;text-align:left;min-height:38px;padding:8px 12px}.folder-actions{display:flex;justify-content:flex-end;gap:8px;padding:12px 16px;border-top:1px solid #303a46}.folder-actions button{padding:9px 14px}
@media(max-width:700px){.controls{grid-template-columns:1fr 1fr}.cwd{grid-column:1/-1}.msg{max-width:94%}}
body{background:#181818;color:#ececec;font-size:14px}main{margin-left:250px;max-width:none;padding:0;gap:0;grid-template-rows:58px 1fr auto auto}#sidebar{position:fixed;inset:0 auto 0 0;width:250px;background:#202020;border-right:1px solid #303030;padding:22px 14px;display:flex;flex-direction:column;gap:10px}#sidebar h2{font-size:15px;margin:0 8px 20px}.nav-title{font-size:11px;color:#929292;margin:20px 10px 4px;letter-spacing:1px}.thread{border:0;background:transparent;color:#c7c7c7;padding:11px 12px;text-align:left;border-radius:8px;font-weight:400;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.thread.active,.thread:hover{background:#343434;color:white}#threads{display:flex;flex-direction:column;overflow:auto;gap:3px}#privacy{margin-top:auto;color:#888;font-size:11px;padding:12px;line-height:1.7}header{padding:0 26px;border-bottom:1px solid #2a2a2a}header h1{font-size:14px;font-weight:500}header .sub{font-size:11px}.danger{background:#333}.actions button{font-size:12px}#chat{padding:28px max(24px,calc((100% - 820px)/2));gap:22px}.msg{max-width:100%;background:transparent;padding:4px 0;border-radius:0}.user{max-width:80%;background:#303030;padding:12px 18px;border-radius:18px}.assistant{width:100%}.notice{background:transparent;color:#999;font-size:12px}.controls{order:4;margin:0 auto 20px;width:min(820px,calc(100% - 48px));border:0;background:transparent;padding:6px 4px;grid-template-columns:auto auto 1fr}.control select{height:28px;background:#252525;border:0}.toggle{height:28px;font-size:12px}.cwd input{height:28px;background:transparent;border:0;font-size:11px}.control>span,.control-title>span{display:none}form{margin:12px auto 0;width:min(820px,calc(100% - 48px));background:#262626;border:1px solid #3b3b3b;border-radius:20px;padding:12px;align-items:end}textarea{border:0;background:transparent;min-height:64px;padding:6px;outline:none}#send{height:34px;width:34px;padding:0;border-radius:50%;background:#ddd;color:#171717;font-size:20px}#stop{height:34px;background:#444;padding:0 12px}.tool-card,.approval-card{border:1px solid #383838;background:#212121;border-radius:12px;padding:12px;width:100%;font-size:12px}.tool-card summary{cursor:pointer;color:#bbb}.tool-card pre,.approval-card pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;color:#bbb}.approval-card button{margin:8px 8px 0 0;padding:8px 14px;background:#eee;color:#222}.approval-card .secondary{background:#444;color:#ddd}#welcome{text-align:center;margin:auto 0;color:#999}#welcome h2{font-size:28px;color:#ececec;font-weight:500}button:focus-visible,select:focus-visible{outline:2px solid #aaa;outline-offset:3px}@media(max-width:760px){#sidebar{width:180px}main{margin-left:180px}header{padding:0 14px}.actions{gap:4px}.actions button{padding:7px}#chat{padding:20px}form,.controls{width:calc(100% - 24px)}}@media(max-width:520px){#sidebar{width:56px;padding:16px 4px}#sidebar h2{font-size:11px;margin:0 0 10px}.nav-title,#privacy{display:none}#sidebar>button{font-size:0;padding:12px 0}#sidebar>button:before{content:'+';font-size:20px}.thread{padding:8px;font-size:11px}main{margin-left:56px}.controls{grid-template-columns:auto auto}.cwd{grid-column:1/-1}}
</style>
<style>.control>span.control-title{display:flex}.control-title>span{display:none}#review{position:fixed;right:0;top:58px;bottom:0;width:min(480px,90vw);padding:20px;background:#202020;border-left:1px solid #444;overflow:auto;z-index:5}#review[hidden]{display:none}#review h2{font-size:16px}#review pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.7 monospace}#review-close{float:right;padding:8px}#review-toggle{padding:9px 13px;background:#333}#review details{border-bottom:1px solid #444;padding:14px 0}#review summary{overflow-wrap:anywhere;cursor:pointer}.diff-add{color:#8bd49b}.diff-remove{color:#ed9999}</style>
</head>
<body><aside id="sidebar"><h2>E4B</h2><button id="new-thread" class="secondary">＋ 新對話</button><button id="open-project" class="secondary">開啟專案</button><div class="nav-title">專案與對話</div><div id="threads"></div><div id="privacy">本機工作 · 對話只在記憶體<br>關閉頁面後不保留對話</div></aside><main>
<header><div><h1>E4B Core</h1><div class="sub">獨立本機 AI · 對話只留在記憶體</div></div><div class="actions"><button id="save" class="secondary">儲存設定</button><button id="reset" class="secondary">新對話</button><button id="shutdown" class="danger">關閉 E4B</button></div></header>
<section class="controls">
  <label class="control"><span>Thinking effort</span><select id="effort"><option value="off">關閉</option><option value="low">低</option><option value="medium" selected>中</option><option value="high">高</option></select></label>
  <label class="toggle"><input id="agent" type="checkbox" checked>啟用 Agent</label>
  <div class="control cwd" id="cwd-wrap"><span class="control-title"><span>目前 Workspace</span><button id="browse" type="button" class="secondary mini">開啟資料夾</button></span><input id="cwd" type="text" readonly placeholder="尚未開啟資料夾"></div>
</section>
<section id="chat"><div id="welcome"><h2>今天要完成什麼？</h2><p>開啟專案，讓 E4B 讀取、修改與驗證你的工作。</p></div><div class="notice">96K context；Agent 的寫檔、編輯與 Shell 操作會先請你批准</div></section>
<form id="form"><textarea id="input" aria-label="工作指令" placeholder="描述工作，或提出問題…" autofocus></textarea><button id="stop" type="button" hidden>停止</button><button id="send" aria-label="送出">↑</button></form>
</main>
<dialog id="folder-dialog"><div class="folder-head"><strong>選擇 Agent 工作目錄</strong><button id="folder-close" class="secondary mini">關閉</button></div><div id="folder-path" class="folder-path"></div><div id="folder-list" class="folder-list"></div><div class="folder-actions"><button id="folder-use">使用這個資料夾</button></div></dialog>
<aside id="review" hidden><button id="review-close">關閉</button><h2>本次修改</h2><p id="review-empty">這個對話尚未修改檔案。</p><div id="review-files"></div></aside>
<script>
const chat=document.querySelector('#chat'),input=document.querySelector('#input'),send=document.querySelector('#send');
const effort=document.querySelector('#effort'),agent=document.querySelector('#agent'),cwd=document.querySelector('#cwd'),cwdWrap=document.querySelector('#cwd-wrap');
const mode=document.createElement('select');mode.id='mode';mode.setAttribute('aria-label','工作模式');for(const [value,label] of [['work','工作'],['plan','規劃']]){const option=document.createElement('option');option.value=value;option.textContent=label;mode.append(option)}document.querySelector('.toggle').append(mode);
const folderDialog=document.querySelector('#folder-dialog'),folderPath=document.querySelector('#folder-path'),folderList=document.querySelector('#folder-list');
let session=crypto.randomUUID(),busy=false,statusNode=null;
window.addEventListener('pagehide',()=>{if(busy)navigator.sendBeacon('/chat/cancel',JSON.stringify({session_id:session}))});
const threads=new Map(),toolCards=new Map();
const review=document.querySelector('#review'),reviewFiles=document.querySelector('#review-files');const reviewButton=document.createElement('button');reviewButton.id='review-toggle';reviewButton.textContent='修改';document.querySelector('.actions').prepend(reviewButton);reviewButton.onclick=()=>review.hidden=!review.hidden;document.querySelector('#review-close').onclick=()=>review.hidden=true;
function rememberThread(){threads.set(session,{nodes:[...chat.childNodes],changes:[...reviewFiles.childNodes],cwd:cwd.value,title:threads.get(session)?.title||'新對話'});renderThreads()}
function renderThreads(){const list=document.querySelector('#threads');list.replaceChildren();for(const [id,thread] of threads){const button=document.createElement('button');button.className='thread'+(id===session?' active':'');button.textContent=(thread.cwd?thread.cwd.split(/[\\/]/).at(-1)+' · ':'')+thread.title;button.title=thread.cwd||thread.title;button.onclick=()=>{if(busy||id===session)return;rememberThread();session=id;cwd.value=thread.cwd;chat.replaceChildren(...thread.nodes);reviewFiles.replaceChildren(...thread.changes);document.querySelector('#review-empty').hidden=reviewFiles.childNodes.length>0;clearStatus();renderThreads()};list.append(button)}}
function newThread(){if(busy)return;rememberThread();session=crypto.randomUUID();chat.replaceChildren();reviewFiles.replaceChildren();document.querySelector('#review-empty').hidden=false;add('notice','已開始新對話');rememberThread();input.focus()}
document.querySelector('#new-thread').onclick=newThread;
document.querySelector('#open-project').onclick=()=>document.querySelector('#browse').click();
document.querySelector('#stop').onclick=async()=>{await fetch('/chat/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:session})});document.querySelector('#stop').disabled=true;add('notice','正在停止工作…')};
rememberThread();
function add(kind,text){const node=document.createElement('div');node.className=(kind==='notice'?'notice':'msg '+kind);node.textContent=text;chat.append(node);chat.scrollTop=chat.scrollHeight;return node}
function eventBlocks(buffer){const blocks=buffer.split('\n\n');return [blocks.slice(0,-1),blocks.at(-1)]}
function clearStatus(){if(statusNode){statusNode.remove();statusNode=null}}
function renderAnswer(node){const raw=node.textContent;node.replaceChildren();let code=null;for(const line of raw.split('\n')){if(line.startsWith('```')){if(code){code=null}else{const pre=document.createElement('pre');code=document.createElement('code');pre.append(code);node.append(pre)}continue}if(code){code.textContent+=line+'\n';continue}const heading=line.match(/^(#{1,3})\s+(.*)/);const item=document.createElement(heading?'h'+(heading[1].length+1):'div');const source=heading?heading[2]:line;const tokens=source.split(/(`[^`]+`|\*\*[^*]+\*\*)/g);for(const token of tokens){const element=document.createElement(token.startsWith('`')?'code':token.startsWith('**')?'strong':'span');element.textContent=token.startsWith('`')?token.slice(1,-1):token.startsWith('**')?token.slice(2,-2):token;item.append(element)}if(!source)item.append(document.createElement('br'));node.append(item)}}
agent.addEventListener('change',()=>{cwdWrap.hidden=!agent.checked});
fetch('/config').then(response=>response.json()).then(value=>{effort.value=value.thinking_effort;agent.checked=value.agent;cwdWrap.hidden=!agent.checked}).catch(()=>{});
document.querySelector('#save').addEventListener('click',async()=>{if(busy)return;const response=await fetch('/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({thinking_effort:effort.value,agent:agent.checked})});if(!response.ok){add('notice','設定儲存失敗：'+await response.text());return}add('notice','Agent 與 thinking effort 設定已儲存')});
document.querySelector('#shutdown').addEventListener('click',async()=>{if(busy||!confirm('關閉 E4B 並釋放 GPU 記憶體？'))return;const response=await fetch('/shutdown',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok){add('notice','關閉失敗：'+await response.text());return}send.disabled=true;input.disabled=true;add('notice','E4B 已關閉；需要時再執行「開啟 E4B.cmd」')});
async function directoryInfo(path){const response=await fetch('/directories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});if(!response.ok){const value=await response.json().catch(()=>({}));throw new Error(value.error||'資料夾不存在')}return response.json()}
async function showDirectory(path,fallback=true){let value;try{value=await directoryInfo(path)}catch(error){if(fallback)value=await directoryInfo('');else throw error}folderPath.textContent=value.current;folderPath.dataset.path=value.current;folderList.replaceChildren();if(value.parent){const up=document.createElement('button');up.className='folder-item';up.textContent='↰ 上一層';up.addEventListener('click',()=>showDirectory(value.parent,false));folderList.append(up)}for(const item of value.directories){const button=document.createElement('button');button.className='folder-item';button.textContent='📁 '+item.name;button.addEventListener('click',()=>showDirectory(item.path,false));folderList.append(button)}}
document.querySelector('#browse').addEventListener('click',async()=>{folderDialog.showModal();try{await showDirectory(cwd.value.trim())}catch(error){folderDialog.close();add('notice','無法開啟資料夾：'+error.message)}});
document.querySelector('#folder-close').addEventListener('click',()=>folderDialog.close());
document.querySelector('#folder-use').addEventListener('click',()=>{if(busy)return;rememberThread();cwd.value=folderPath.dataset.path;session=crypto.randomUUID();folderDialog.close();chat.replaceChildren();reviewFiles.replaceChildren();document.querySelector('#review-empty').hidden=false;add('notice','已開啟 Workspace：'+cwd.value+'；這是新的對話 context');rememberThread()});
async function approve(payload){
  const details=payload.preview||JSON.stringify(payload.arguments,null,2);
  const accepted=await new Promise(resolve=>{const card=document.createElement('section');card.className='approval-card';const title=document.createElement('strong');title.textContent='需要批准 · '+payload.tool;const pre=document.createElement('pre');pre.textContent=details;card.append(title,pre);for(const [label,value] of [['允許這次操作',true],['拒絕',false]]){const button=document.createElement('button');button.textContent=label;if(!value)button.className='secondary';button.onclick=()=>{card.replaceChildren(title);title.textContent=value?'已批准 · '+payload.tool:'已拒絕 · '+payload.tool;resolve(value)};card.append(button)}chat.append(card);card.scrollIntoView({block:'nearest'});document.querySelector('#stop').addEventListener('click',()=>resolve(false),{once:true})});
  const response=await fetch('/chat/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:session,call_id:payload.call_id,approved:accepted})});
  if(!response.ok)throw new Error(await response.text());
}
async function handleEvent(type,payload,answer){
  if(type==='delta'){clearStatus();answer.textContent+=payload.text;chat.scrollTop=chat.scrollHeight}
  else if(type==='status'){clearStatus();statusNode=add('notice',payload.message)}
  else if(type==='compacted'){add('notice',payload.message)}
  else if(type==='approval'){clearStatus();await approve(payload);statusNode=add('notice','等待 Agent 繼續…')}
  else if(type==='tool'){clearStatus();let card=toolCards.get(payload.call_id);if(payload.phase==='running'){card=document.createElement('details');card.className='tool-card';const title=document.createElement('summary');title.textContent='執行中 · '+payload.tool;const pre=document.createElement('pre');pre.textContent=JSON.stringify(payload.arguments,null,2);card.append(title,pre);chat.append(card);toolCards.set(payload.call_id,card)}else if(card){card.querySelector('summary').textContent='已結束 · '+payload.tool;const pre=document.createElement('pre');pre.textContent=payload.result;card.append(pre)}}
  else if(type==='cancelled'){clearStatus();add('notice','工作已停止')}
  else if(type==='change'){document.querySelector('#review-empty').hidden=true;let card=[...reviewFiles.children].find(node=>node.dataset.path===payload.path);if(!card){card=document.createElement('details');card.dataset.path=payload.path;reviewFiles.append(card)}card.replaceChildren();const title=document.createElement('summary');title.textContent=payload.path;const pre=document.createElement('pre');for(const line of payload.diff.split('\n')){const span=document.createElement('span');span.textContent=line+'\n';if(line.startsWith('+'))span.className='diff-add';if(line.startsWith('-'))span.className='diff-remove';pre.append(span)}card.append(title,pre);reviewButton.textContent='修改 · '+reviewFiles.children.length}
  else if(type==='error'){throw new Error(payload.message)}
}
async function ask(text){
  if(agent.checked&&!cwd.value.trim()){add('notice','請先按「開啟資料夾」選擇這次要使用的 Workspace。');return}
  if(agent.checked){try{await directoryInfo(cwd.value.trim())}catch(error){add('notice','Workspace 無效：'+error.message+'；請重新開啟資料夾。');return}}
  busy=true;send.disabled=true;document.querySelector('#stop').hidden=false;document.querySelector('#stop').disabled=false;document.querySelector('#welcome')?.remove();if(threads.get(session)?.title==='新對話'){threads.get(session).title=text.slice(0,28);renderThreads()}add('user',text);const answer=add('assistant','');
  try{
    const body={session_id:session,text,thinking_effort:effort.value,agent:agent.checked,plan:mode.value==='plan',working_dir:cwd.value.trim()};
    const response=await fetch('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error(await response.text());
    const reader=response.body.getReader(),decoder=new TextDecoder();let pending='';
    while(true){
      const {value,done}=await reader.read();pending+=decoder.decode(value||new Uint8Array(),{stream:!done});const [blocks,rest]=eventBlocks(pending);pending=rest;
      for(const block of blocks){let type='message',data='{}';for(const line of block.split('\n')){if(line.startsWith('event: '))type=line.slice(7);if(line.startsWith('data: '))data=line.slice(6)}await handleEvent(type,JSON.parse(data),answer)}
      if(done)break;
    }
    clearStatus();if(!answer.textContent)answer.remove();else renderAnswer(answer);
  }catch(error){clearStatus();answer.textContent='錯誤：'+error.message}
  finally{busy=false;send.disabled=false;document.querySelector('#stop').hidden=true;rememberThread();input.focus()}
}
document.querySelector('#form').addEventListener('submit',event=>{event.preventDefault();const text=input.value.trim();if(!text||busy)return;input.value='';ask(text)});
input.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();document.querySelector('#form').requestSubmit()}});
document.querySelector('#reset').addEventListener('click',newThread);
</script></body></html>"""
